fn list_deep_clone(arr: &Vec<u64>) -> Vec<u64> {
    // Pre-allocate a new Vec with the same capacity to avoid reallocations
    let mut copied: Vec<u64> = Vec::with_capacity(arr.len());

    // Deep-copy each element
    for &value in arr.iter() {
        copied.push(value);
    }

    copied
}

